{
  "narratives": [
    {
      "item_code": "S5_MEDIA",
      "title_raw": "가. 적절한(및 부적절한) 소화제",
      "start": "p3:L19",
      "end": "p3:L21"
    },
    {
      "item_code": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "start": "p3:L23",
      "end": "p3:L28"
    },
    {
      "item_code": "S5_FIREFIGHT",
      "title_raw": "다. 화재 진압 시 착용할 보호구 및 예방조치",
      "start": "p3:L29",
      "end": "p3:L34"
    }
  ]
,
  "extras": [
    {
      "after_item": "S5_MEDIA",
      "title_raw": "가. 적절한(및 부적절한) 소화제",
      "reason": "코드없음",
      "statements": [
        {
          "key": "적절한 소화제",
          "value": "분말소화제, 이산화탄소, 일반 포말소화제, 물 분무"
        ,
          "line": "p3:L20"
        },
        {
          "key": "부적절한 소화제",
          "value": "직사주수를 사용한 소화"
        ,
          "line": "p3:L21"
        }
      ]
    ,
      "line": "p3:L19"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "reason": "코드없음",
      "statements": [
        {
          "value": "금속을 부식시킬 수 있음"
        ,
          "line": "p3:L24"
        },
        {
          "value": "눈에 심한 손상을 일으킴"
        ,
          "line": "p3:L25"
        },
        {
          "value": "삼키면 유해함"
        ,
          "line": "p3:L26"
        },
        {
          "value": "알레르기성 피부 반응을 일으킬 수 있음"
        ,
          "line": "p3:L27"
        },
        {
          "value": "장기적인 영향에 의해 수생생물에게 유해함"
        ,
          "line": "p3:L28"
        }
      ]
    ,
      "line": "p3:L23"
    },
    {
      "after_item": "S5_FIREFIGHT",
      "title_raw": "다. 화재 진압 시 착용할 보호구 및 예방조치",
      "reason": "코드없음",
      "statements": [
        {
          "value": "관계인 외 접근을 막고 위험 지역의 출입을 금지하시오."
        ,
          "line": "p3:L30"
        },
        {
          "value": "물질 자체 또는 연소 생성물의 흡입을 피하시오."
        ,
          "line": "p3:L31"
        },
        {
          "value": "소방서에 알리고, 화재 위치와 유해한 특징을 알려주시오."
        ,
          "line": "p3:L32"
        },
        {
          "value": "위험 없이 할 수 있다면 용기를 화재지역으로부터 이동시키시오."
        ,
          "line": "p3:L33"
        },
        {
          "value": "탱크가 화염에 휩싸였을 경우에는 접근하지 마시오."
        ,
          "line": "p3:L34"
        }
      ]
    ,
      "line": "p3:L29"
    }
  ]
}

